var e=[{lesson:1,arabic:`أُمُّ الْقُرْآنِ`,russian:`«Мать Корана»; одно из названий суры аль-Фатиха`,kind:`term`},{lesson:1,arabic:`الْمَثَانِي`,russian:`«Повторяемые [аяты]»; название аль-Фатихи, читаемой в каждой молитве`,kind:`term`},{lesson:1,arabic:`السَّامُ`,russian:`смерть`,kind:`noun`},{lesson:1,arabic:`التَّسْمِيَةُ`,russian:`произнесение басмалы: «Бисми-Лляхи-р-Рахмани-р-Рахим»`,kind:`term`},{lesson:1,arabic:`الدَّرْجُ`,russian:`слитное произнесение слова внутри речи, не начиная с него`,kind:`term`},{lesson:1,arabic:`عَجُزٌ ج أَعْجَازٌ`,russian:`конец слова, его конечная часть`,kind:`term`},{lesson:1,arabic:`سُمُوٌّ`,russian:`возвышенность, высота`,kind:`masdar`},{lesson:1,arabic:`الثُّرَيَّا`,russian:`Плеяды; скопление звёзд`,kind:`noun`},{lesson:1,arabic:`أَلِهَ – يَأْلَهُ`,russian:`быть в растерянности, изумляться`,kind:`verb`},{lesson:1,arabic:`أَلَهَ – يَأْلَهُ`,russian:`поклоняться`,kind:`verb`},{lesson:1,arabic:`نِحْرِيرٌ ج نَحَارِيرُ`,russian:`проницательный, искусный знаток; глубокий учёный`,kind:`noun`},{lesson:1,arabic:`إِلَهٌ`,russian:`поклонение; масдар أَلَهَ, а не существительное «божество»`,kind:`masdar`},{lesson:2,arabic:`رَبَّ – يَرُبُّ`,russian:`владеть; управлять и воспитывать`,kind:`verb`},{lesson:2,arabic:`رَبٌّ`,russian:`владение, управление; масдар глагола رَبَّ`,kind:`masdar`},{lesson:2,arabic:`كَمَا تَدِينُ تُدَانُ`,russian:`как поступаешь, так тебе и воздаётся`,kind:`expression`},{lesson:2,arabic:`يَوْمُ الدِّينِ`,russian:`День воздаяния`,kind:`term`},{lesson:3,arabic:`إِثْمِدٌ`,russian:`сурьма для подведения глаз; в стихе — название места`,kind:`noun`},{lesson:3,arabic:`خَلِيٌّ`,russian:`свободный от забот и сердечной привязанности`,kind:`adjective`},{lesson:3,arabic:`عَائِرٌ`,russian:`соринка в глазу; болезненное раздражение глаза`,kind:`noun`},{lesson:3,arabic:`أَرْمَدُ`,russian:`страдающий воспалением глаз`,kind:`adjective`},{lesson:3,arabic:`حَاذِقٌ ج حُذَّاقٌ`,russian:`искусный знаток, мастер`,kind:`noun`},{lesson:3,arabic:`سَرَطَ – يَسْرُطُ`,russian:`проглотить`,kind:`verb`},{lesson:3,arabic:`حُرُوفُ الْإِطْبَاقِ`,russian:`эмфатические согласные ص، ض، ط، ظ, при произнесении которых язык приподнимается к нёбу`,kind:`term`},{lesson:3,arabic:`إِشْمَامُ الصَّادِ صَوْتَ الزَّايِ`,russian:`примесь звучания ز к ص в определённом чтении`,kind:`term`},{lesson:3,arabic:`الْمُصْحَفُ الْإِمَامُ`,russian:`главный, образцовый мусхаф`,kind:`term`},{lesson:3,arabic:`كَلِيلٌ`,russian:`утомлённый, утративший остроту; здесь — о зрении`,kind:`adjective`},{lesson:4,arabic:`فَوَاتِحُ السُّوَرِ`,russian:`начала сур; здесь — раздельно читаемые буквенные начала некоторых сур`,kind:`term`},{lesson:4,arabic:`الْحُرُوفُ الْمُعْجَمَةُ`,russian:`буквы алфавита; в объяснении автора — обозначения, смысл которых неясен без толкования`,kind:`term`},{lesson:4,arabic:`الْحُرُوفُ الْمَهْمُوسَةُ`,russian:`согласные, произносимые с течением дыхания`,kind:`term`},{lesson:4,arabic:`الْحُرُوفُ الْمَجْهُورَةُ`,russian:`согласные, при произнесении которых дыхание удерживается`,kind:`term`},{lesson:4,arabic:`الْحُرُوفُ الشَّدِيدَةُ`,russian:`согласные, при произнесении которых течение звука перекрывается`,kind:`term`},{lesson:4,arabic:`الْحُرُوفُ الرِّخْوَةُ`,russian:`согласные с непрерывным течением звука`,kind:`term`},{lesson:4,arabic:`الْحُرُوفُ الْمُسْتَعْلِيَةُ`,russian:`согласные, произносимые с подъёмом языка к нёбу`,kind:`term`},{lesson:4,arabic:`حُرُوفُ الْقَلْقَلَةِ`,russian:`согласные ق، ط، ب، ج، د с характерным отскоком звука при сукуне`,kind:`term`},{lesson:4,arabic:`وَقْفُ التَّمَامِ`,russian:`полная остановка чтения там, где смысл завершён`,kind:`term`},{lesson:4,arabic:`غَاقِ`,russian:`подражание крику ворона`,kind:`noun`},{lesson:4,arabic:`وَتِيرَةٌ`,russian:`устойчивый порядок, однообразный образ действий`,kind:`noun`},{lesson:4,arabic:`اِفْتِنَانٌ فِي الْكَلَامِ`,russian:`разнообразие способов выражения, переход от одного речевого приёма к другому`,kind:`term`},{lesson:4,arabic:`رَيْبُ الزَّمَانِ`,russian:`превратности времени, тревожащие бедствия`,kind:`expression`},{lesson:4,arabic:`غَوْلٌ`,russian:`вредное действие вина, помрачение разума`,kind:`noun`},{lesson:4,arabic:`الزَّهْرَاوَانِ`,russian:`«две светозарные» суры: аль-Бакара и Аль Имран`,kind:`term`},{lesson:4,arabic:`تَبَخْتَرَ – يَتَبَخْتَرُ`,russian:`выступать горделиво; переносно — ярко и уверенно обнаруживаться`,kind:`verb`},{lesson:4,arabic:`اِكْتَنَهَ – يَكْتَنِهُ`,russian:`постигнуть сущность и глубину чего-либо`,kind:`verb`},{lesson:4,arabic:`سُطُوعٌ`,russian:`сияние, яркое проявление`,kind:`masdar`},{lesson:4,arabic:`نَعَقَ – يَنْعِقُ`,russian:`каркать; кричать, подавая голос`,kind:`verb`},{lesson:4,arabic:`حَامَ – يَحُومُ`,russian:`кружить вокруг`,kind:`verb`},{lesson:4,arabic:`أَنِيقٌ`,russian:`изящный, прекрасный`,kind:`adjective`},{lesson:4,arabic:`رَشِيقٌ`,russian:`стройный, лёгкий и изящный`,kind:`adjective`},{lesson:4,arabic:`فَخَامَةٌ`,russian:`величие, внушительность`,kind:`masdar`},{lesson:4,arabic:`اِغْتَالَ – يَغْتَالُ`,russian:`погубить скрытым воздействием; лишить разума`,kind:`verb`},{lesson:5,arabic:`عِيَارٌ`,russian:`мера, критерий оценки`,kind:`noun`},{lesson:5,arabic:`الصَّلَوَانِ`,russian:`две части таза у основания позвоночника; в объяснении автора — ягодицы`,kind:`noun`},{lesson:5,arabic:`قَرْمٌ`,russian:`знатный предводитель, выдающийся муж`,kind:`noun`},{lesson:5,arabic:`غَارِبٌ`,russian:`верхняя часть спины животного за шеей; переносно — то, на что опираются`,kind:`noun`},{lesson:5,arabic:`اِقْتَعَدَ – يَقْتَعِدُ`,russian:`взобраться верхом, занять место на спине животного`,kind:`verb`},{lesson:5,arabic:`فَلَذَ – يَفْلِذُ`,russian:`отрезать кусок`,kind:`verb`},{lesson:5,arabic:`فَلَى – يَفْلِي`,russian:`рассекать; выискивать и удалять вшей`,kind:`verb`},{lesson:6,arabic:`غِشَاوَةٌ`,russian:`покров, пелена`,kind:`noun`},{lesson:6,arabic:`نَكَالٌ`,russian:`наказание, удерживающее других от подобного проступка`,kind:`noun`},{lesson:7,arabic:`عَمِهَ – يَعْمَهُ`,russian:`блуждать в растерянности и заблуждении`,kind:`verb`},{lesson:7,arabic:`عَمَهٌ`,russian:`растерянное блуждание, внутренняя слепота`,kind:`masdar`},{lesson:7,arabic:`اِسْتَجْهَلَ – يَسْتَجْهِلُ`,russian:`считать невеждой, объявлять неразумным`,kind:`verb`},{lesson:7,arabic:`مِرْجَاحٌ ج مَرَاجِيحُ`,russian:`степенный и разумный человек`,kind:`noun`},{lesson:7,arabic:`مَئِنَّةٌ لِـ`,russian:`признак, указание на что-либо`,kind:`noun`},{lesson:7,arabic:`هُزْءٌ`,russian:`быстрая смерть или быстрое умерщвление; не «насмешка»`,kind:`masdar`},{lesson:7,arabic:`هَزَأَ – يَهْزَأُ`,russian:`умереть на месте`,kind:`verb`},{lesson:7,arabic:`نِكَايَةٌ`,russian:`тяжёлый урон, поражение`,kind:`noun`},{lesson:7,arabic:`جِبِلَّةٌ`,russian:`врождённая природа, естество`,kind:`noun`},{lesson:7,arabic:`مَشَاعِرُ الْإِنْسَانِ`,russian:`органы чувств человека`,kind:`expression`},{lesson:7,arabic:`مَاثَلَ – يُمَاثِلُ`,russian:`уподобиться, оказаться подобным`,kind:`verb`},{lesson:7,arabic:`شَطَنَ – يَشْطُنُ`,russian:`удалиться, быть далёким`,kind:`verb`},{lesson:7,arabic:`تَشَيْطَنَ – يَتَشَيْطَنُ`,russian:`стать подобным шайтану, проявить крайнее своеволие`,kind:`verb`},{lesson:8,arabic:`صَيِّبٌ`,russian:`сильный ливень; также несущая дождь туча`,kind:`noun`},{lesson:8,arabic:`أَسْحَمُ`,russian:`густо-чёрный, тёмный`,kind:`adjective`},{lesson:8,arabic:`دَاجٍ`,russian:`тёмный, покрытый мраком`,kind:`adjective`},{lesson:8,arabic:`الْمُسَبِّحَةُ`,russian:`указательный палец, которым указывают при поминании Аллаха`,kind:`noun`},{lesson:8,arabic:`اِصْطَكَّ – يَصْطَكُّ`,russian:`сильно ударяться друг о друга`,kind:`verb`},{lesson:8,arabic:`خَفَقَ – يَخْفِقُ`,russian:`вспыхивать, сверкать; здесь — о молнии`,kind:`verb`},{lesson:8,arabic:`خُفُوقٌ`,russian:`вспышка, сверкание молнии`,kind:`masdar`},{lesson:8,arabic:`خُفُوتٌ`,russian:`угасание, ослабление света`,kind:`masdar`},{lesson:8,arabic:`خَفْقَةٌ`,russian:`одна короткая вспышка`,kind:`noun`},{lesson:8,arabic:`لَمَعَانٌ`,russian:`блеск, сверкание`,kind:`masdar`},{lesson:8,arabic:`اِسْتَوْقَدَ – يَسْتَوْقِدُ`,russian:`разжечь, потребовать разведения огня`,kind:`verb`},{lesson:8,arabic:`قَاصِفٌ`,russian:`громовой, сильно грохочущий; о громе`,kind:`adjective`},{lesson:9,arabic:`حَوْبَةٌ`,russian:`грех, провинность`,kind:`noun`},{lesson:9,arabic:`نَوَالٌ`,russian:`дар, щедрое пожалование`,kind:`noun`},{lesson:9,arabic:`الِاسْتِرْجَاعُ`,russian:`произнесение «Инна ли-Лляхи ва-инна иляйхи раджи‘ун» при бедствии`,kind:`term`},{lesson:9,arabic:`حُنُوٌّ`,russian:`нежность, сострадание, ласковое отношение`,kind:`masdar`},{lesson:9,arabic:`الْعِدْلَانِ وَالْعِلَاوَةُ`,russian:`два боковых груза и верхняя добавка; образ для трёх дарованных благ`,kind:`expression`},{lesson:10,arabic:`سِنَةٌ`,russian:`дремота, начало сна`,kind:`noun`},{lesson:10,arabic:`آدَ – يَؤُودُ`,russian:`отяготить, изнурить`,kind:`verb`},{lesson:10,arabic:`كُرْسِيٌّ`,russian:`Курси; здесь в дополнительных толкованиях автора — знание, власть или могущество`,kind:`term`},{lesson:10,arabic:`فُتُورٌ`,russian:`ослабление бодрости, вялость перед сном`,kind:`masdar`},{lesson:11,arabic:`أَصَرَ – يَأْصِرُ`,russian:`удерживать на месте тяжестью, связывать`,kind:`verb`},{lesson:11,arabic:`مَسْخٌ`,russian:`изменение человеческого облика в иной как наказание`,kind:`term`},{lesson:12,arabic:`وَسْوَاسٌ`,russian:`наущатель; название шайтана, внушающего дурные мысли`,kind:`noun`},{lesson:12,arabic:`خُنُوسٌ`,russian:`отступление, исчезновение из виду`,kind:`masdar`},{lesson:12,arabic:`الْخَنَّاسُ`,russian:`тот, кто прячется и отступает; эпитет шайтана`,kind:`term`},{lesson:12,arabic:`مَشَاطَةٌ`,russian:`волосы, оставшиеся на гребне после расчёсывания`,kind:`noun`},{lesson:12,arabic:`جُفُّ طَلْعَةٍ`,russian:`оболочка пальмового соцветия`,kind:`expression`},{lesson:12,arabic:`رَاعُوفَةٌ`,russian:`камень на дне колодца, на который становится чистящий колодец`,kind:`noun`},{lesson:12,arabic:`طَبَّ – يَطُبُّ`,russian:`околдовать; не «лечить»`,kind:`verb`},{lesson:12,arabic:`الِاسْتِرْقَاءُ`,russian:`просьба прочитать рукъю; здесь — специальный вопрос о дозволенном защитном чтении`,kind:`term`},{lesson:12,arabic:`كَأَنَّمَا نُشِطَ مِنْ عِقَالٍ`,russian:`словно освободился от пут; о внезапном избавлении от болезни или стеснения`,kind:`expression`},{lesson:12,arabic:`نَشَطَ – يَنْشُطُ`,russian:`вытянуть, извлечь; освободить от пут`,kind:`verb`},{lesson:12,arabic:`وَسْوَسَ – يُوَسْوِسُ`,russian:`нашёптывать дурные мысли, наущать`,kind:`verb`},{lesson:13,arabic:`فَلَقٌ`,russian:`рассвет, утренняя заря`,kind:`noun`},{lesson:13,arabic:`غَاسِقٌ`,russian:`наступающая ночь, ночной мрак`,kind:`noun`},{lesson:13,arabic:`وَقَبَ – يَقِبُ`,russian:`входить, проникать; здесь — о наступлении ночной тьмы`,kind:`verb`},{lesson:13,arabic:`وُقُوبٌ`,russian:`вхождение, наступление темноты`,kind:`masdar`},{lesson:13,arabic:`اِعْتَكَرَ – يَعْتَكِرُ`,russian:`сгуститься; здесь — о ночной тьме`,kind:`verb`},{lesson:13,arabic:`النَّفَّاثَاتُ فِي الْعُقَدِ`,russian:`колдуньи, дующие на узлы при колдовстве`,kind:`term`},{lesson:14,arabic:`صَمَدَ – يَصْمُدُ إِلَى`,russian:`обращаться к кому-либо, направляться к нему за помощью`,kind:`verb`},{lesson:15,arabic:`تَبَّ – يَتِبُّ`,russian:`погибнуть, потерпеть крушение`,kind:`verb`},{lesson:15,arabic:`تَبَابٌ`,russian:`гибель, крушение`,kind:`masdar`},{lesson:15,arabic:`أَوْبٌ`,russian:`сторона, направление; здесь не «возвращение»`,kind:`noun`},{lesson:15,arabic:`تَالِدٌ`,russian:`давно приобретённое или унаследованное имущество`,kind:`noun`},{lesson:15,arabic:`طَارِفٌ`,russian:`недавно приобретённое имущество`,kind:`noun`},{lesson:15,arabic:`مَسَدٌ`,russian:`свитое пальмовое волокно; верёвка из него`,kind:`noun`},{lesson:15,arabic:`حَسَكٌ`,russian:`колючки, острые шипы`,kind:`noun`},{lesson:15,arabic:`حَمَّالَةُ الْحَطَبِ`,russian:`«носильщица дров»; также переносно — разносящая сплетни и разжигающая вражду`,kind:`expression`},{lesson:15,arabic:`جِدَةٌ`,russian:`богатство, достаток; не «новизна»`,kind:`noun`},{lesson:16,arabic:`نَاوَأَ – يُنَاوِئُ`,russian:`противодействовать, враждовать`,kind:`verb`},{lesson:16,arabic:`هَضْمُ النَّفْسِ`,russian:`умаление собственного достоинства, смирение`,kind:`expression`},{lesson:17,arabic:`نَابَذَ – يُنَابِذُ`,russian:`отмежеваться от кого-либо, открыто разорвать отношения`,kind:`verb`},{lesson:18,arabic:`الْكَوْثَرُ`,russian:`обильное благо; также название реки в Раю`,kind:`term`},{lesson:18,arabic:`زَبَرْجَدٌ`,russian:`хризолит; зелёный драгоценный камень`,kind:`noun`},{lesson:18,arabic:`أَبْتَرُ`,russian:`лишённый продолжения рода или доброй памяти; отсечённый от блага`,kind:`adjective`},{lesson:18,arabic:`رَاغَمَ – يُرَاغِمُ`,russian:`противостоять, унизить противника своим успехом`,kind:`verb`},{lesson:19,arabic:`مَاعُونٌ`,russian:`мелкие полезные вещи, которые дают взаймы; в одном толковании — закят`,kind:`noun`},{lesson:19,arabic:`جَفْوَةٌ`,russian:`грубость, жестокость в обращении`,kind:`noun`},{lesson:19,arabic:`تَعَاوَرَ – يَتَعَاوَرُ`,russian:`передавать друг другу во временное пользование`,kind:`verb`},{lesson:19,arabic:`مِقْدَحَةٌ`,russian:`огниво, орудие для высекания огня`,kind:`noun`},{lesson:20,arabic:`التَّضْمِينُ فِي الشِّعْرِ`,russian:`зависимость смысла стихотворной строки от другой строки`,kind:`term`},{lesson:20,arabic:`قِرْشٌ`,russian:`акула`,kind:`noun`},{lesson:20,arabic:`قَرْشٌ`,russian:`собирание, приобретение имущества`,kind:`masdar`},{lesson:20,arabic:`اِمْتَارَ – يَمْتَارُ`,russian:`запастись продовольствием, приобрести зерно`,kind:`verb`},{lesson:20,arabic:`عَصْفٌ`,russian:`сухие стебли и листья посевов, мякина`,kind:`noun`},{lesson:21,arabic:`أَبَابِيلُ`,russian:`стаи, разрозненные группы птиц`,kind:`noun`},{lesson:21,arabic:`سِجِّيلٌ`,russian:`обожжённая или затвердевшая глина`,kind:`noun`},{lesson:21,arabic:`ضَلَّلَ – يُضَلِّلُ الْكَيْدَ`,russian:`свести коварный замысел на нет, сделать его тщетным`,kind:`verb`},{lesson:21,arabic:`عِيرٌ`,russian:`караван с поклажей; не عَيْرٌ «осёл»`,kind:`noun`},{lesson:21,arabic:`اِنْصَدَعَ – يَنْصَدِعُ`,russian:`расколоться, треснуть`,kind:`verb`},{lesson:21,arabic:`اِنْفَلَتَ – يَنْفَلِتُ`,russian:`вырваться, ускользнуть`,kind:`verb`},{lesson:22,arabic:`هُمَزَةٌ`,russian:`злословящий за спиной, по различению автора`,kind:`noun`},{lesson:22,arabic:`لُمَزَةٌ`,russian:`поносящий человека в лицо, по различению автора`,kind:`noun`},{lesson:22,arabic:`الْحُطَمَةُ`,russian:`«сокрушающая»; название адского огня`,kind:`term`},{lesson:24,arabic:`عَيْنُ الْيَقِينِ`,russian:`непосредственное, воочию полученное удостоверение`,kind:`term`},{lesson:24,arabic:`كِنٌّ`,russian:`укрытие, защищающее от непогоды`,kind:`noun`},{lesson:25,arabic:`الْقَارِعَةُ`,russian:`«потрясающая»; одно из названий Судного дня`,kind:`term`},{lesson:25,arabic:`عِهْنٌ`,russian:`окрашенная шерсть`,kind:`noun`},{lesson:25,arabic:`الْهَاوِيَةُ`,russian:`«бездна»; название Ада`,kind:`term`},{lesson:26,arabic:`ضَبَحَ – يَضْبَحُ`,russian:`тяжело дышать на бегу; о коне`,kind:`verb`},{lesson:26,arabic:`ضَبْحٌ`,russian:`хриплое дыхание скачущего коня`,kind:`masdar`},{lesson:26,arabic:`قَدْحٌ`,russian:`высекание искры ударом; не «порицание»`,kind:`masdar`},{lesson:26,arabic:`أَوْرَى – يُورِي`,russian:`высечь, зажечь огонь`,kind:`verb`},{lesson:26,arabic:`أَصْلَدَ – يُصْلِدُ`,russian:`не дать искры при высекании огня`,kind:`verb`},{lesson:26,arabic:`نَارُ الْحُبَاحِبِ`,russian:`слабые искры; образное название очень слабого огня`,kind:`expression`},{lesson:26,arabic:`نَقْعٌ`,russian:`поднятая пыль; не «замачивание»`,kind:`noun`},{lesson:26,arabic:`كَنُودٌ`,russian:`неблагодарный, отрицающий оказанное ему благо`,kind:`adjective`},{lesson:26,arabic:`حَصَّلَ – يُحَصِّلُ`,russian:`выделить, обнаружить скрытое; здесь — выявить содержимое сердец`,kind:`verb`},{lesson:26,arabic:`اِنْقَدَحَ – يَنْقَدِحُ`,russian:`вспыхнуть, возникнуть в виде искры`,kind:`verb`},{lesson:27,arabic:`ثِقْلٌ ج أَثْقَالٌ`,russian:`бремя, тяжёлое содержимое; здесь — мёртвые и сокровища в земле`,kind:`noun`},{lesson:27,arabic:`دَفِينَةٌ ج دَفَائِنُ`,russian:`скрытое в земле сокровище`,kind:`noun`},{lesson:27,arabic:`ذَرَّةٌ`,russian:`крошечный муравей; мельчайшая видимая частица`,kind:`noun`},{lesson:27,arabic:`أَشْتَاتٌ`,russian:`разрозненные группы, порознь`,kind:`noun`},{lesson:28,arabic:`الْبَرِيَّةُ`,russian:`создания, сотворённые существа`,kind:`noun`},{lesson:28,arabic:`الْبَيِّنَةُ`,russian:`Баййина; здесь — посланник и ниспосланное ему откровение, а не судебное доказательство`,kind:`term`},{lesson:28,arabic:`عَدْنٌ`,russian:`постоянное пребывание, поселение`,kind:`masdar`},{lesson:28,arabic:`جَنَّاتُ عَدْنٍ`,russian:`сады вечного пребывания`,kind:`expression`},{lesson:30,arabic:`الرُّجْعَى`,russian:`возвращение`,kind:`masdar`},{lesson:30,arabic:`سَفَعَ – يَسْفَعُ`,russian:`схватить, резко потянуть`,kind:`verb`},{lesson:30,arabic:`سَفْعٌ`,russian:`схватывание, резкое притягивание`,kind:`masdar`},{lesson:30,arabic:`الزَّبَانِيَةُ`,russian:`ангелы, карающие обитателей Ада`,kind:`term`},{lesson:30,arabic:`زَبَنَ – يَزْبُنُ`,russian:`оттолкнуть, грубо прогнать`,kind:`verb`},{lesson:30,arabic:`زَبْنٌ`,russian:`отталкивание, грубое прогоняние`,kind:`masdar`},{lesson:31,arabic:`بَاسُورٌ ج بَوَاسِيرُ`,russian:`геморроидальное поражение`,kind:`noun`},{lesson:31,arabic:`نِقْرِسٌ`,russian:`подагра`,kind:`noun`},{lesson:31,arabic:`حَفَرٌ`,russian:`поражение зубов, описанное автором как пожелтение`,kind:`noun`},{lesson:31,arabic:`عَجَمٌ`,russian:`косточки плодов`,kind:`noun`},{lesson:31,arabic:`تَشَنَّنَ – يَتَشَنَّنُ`,russian:`высохнуть, сморщиться; здесь — о коже`,kind:`verb`},{lesson:31,arabic:`دَلِيفٌ`,russian:`слабый, медленный шаг старика`,kind:`noun`},{lesson:31,arabic:`خُفَاتٌ`,russian:`ослабевший, едва слышный голос`,kind:`noun`},{lesson:31,arabic:`غَيْرُ مَمْنُونٍ`,russian:`непрерывный, не прекращающийся; о награде`,kind:`expression`},{lesson:32,arabic:`أَنْقَضَ – يُنْقِضُ`,russian:`отяготить до хруста; о тяжести, давящей на спину`,kind:`verb`},{lesson:32,arabic:`نَقِيضٌ`,russian:`хруст, скрип; не «противоположность»`,kind:`noun`},{lesson:32,arabic:`ذَنَّبَ – يُذَنِّبُ`,russian:`присоединить следом; здесь — вслед за одним поклонением совершить другое`,kind:`verb`},{lesson:33,arabic:`سَجَا – يَسْجُو`,russian:`утихнуть, успокоиться; о ночи`,kind:`verb`},{lesson:33,arabic:`قَلَى – يَقْلِي`,russian:`ненавидеть, возненавидеть`,kind:`verb`},{lesson:33,arabic:`قِلًى`,russian:`ненависть, неприязнь`,kind:`masdar`},{lesson:33,arabic:`قَاذُورَةٌ ج قَاذُورَاتٌ`,russian:`мерзость, постыдный поступок`,kind:`noun`},{lesson:34,arabic:`الرَّدَى`,russian:`гибель`,kind:`masdar`},{lesson:34,arabic:`تَرَدَّى – يَتَرَدَّى`,russian:`погибнуть; упасть в пропасть`,kind:`verb`},{lesson:34,arabic:`تَلَظَّى – يَتَلَظَّى`,russian:`полыхать, пылать`,kind:`verb`},{lesson:35,arabic:`طَحَا – يَطْحُو`,russian:`расстелить, распростереть`,kind:`verb`},{lesson:35,arabic:`طَحْوٌ`,russian:`расстилание, распространение`,kind:`masdar`},{lesson:35,arabic:`دَسَّى – يُدَسِّي`,russian:`скрыть, подавить, осквернить; здесь — погубить душу нечестием`,kind:`verb`},{lesson:35,arabic:`طَغْوَى`,russian:`чрезмерность, преступание границ`,kind:`masdar`},{lesson:36,arabic:`كَبَدٌ`,russian:`тягота, трудности; не «печень»`,kind:`noun`},{lesson:36,arabic:`لُبَدٌ`,russian:`множество, скопившаяся масса; здесь — большое богатство`,kind:`noun`},{lesson:36,arabic:`النَّجْدَانِ`,russian:`два пути: добра и зла; в другом толковании — две груди`,kind:`term`},{lesson:36,arabic:`قُحْمَةٌ`,russian:`тяжёлое испытание, труднопреодолимая преграда`,kind:`noun`},{lesson:36,arabic:`مَسْغَبَةٌ`,russian:`голод, нужда в пище`,kind:`noun`},{lesson:36,arabic:`مَتْرَبَةٌ`,russian:`крайняя бедность`,kind:`noun`},{lesson:36,arabic:`سَغِبَ – يَسْغَبُ`,russian:`голодать`,kind:`verb`},{lesson:36,arabic:`تَرِبَ – يَتْرَبُ`,russian:`обеднеть, впасть в нужду`,kind:`verb`},{lesson:36,arabic:`أَصْحَابُ الْمَيْمَنَةِ`,russian:`«люди правой стороны»; счастливые, спасённые в Последней жизни`,kind:`term`},{lesson:36,arabic:`أَصْحَابُ الْمَشْأَمَةِ`,russian:`«люди левой стороны»; несчастные, обречённые на наказание`,kind:`term`},{lesson:36,arabic:`أَوْصَدَ – يُوصِدُ`,russian:`плотно закрыть, запереть`,kind:`verb`},{lesson:36,arabic:`آصَدَ – يُؤْصِدُ`,russian:`плотно закрыть, запереть; вариант أَوْصَدَ`,kind:`verb`},{lesson:37,arabic:`حِجْرٌ`,russian:`разум, удерживающий от недостойного; не «запрет»`,kind:`noun`},{lesson:37,arabic:`جَابَ – يَجُوبُ`,russian:`рассекать, вырубать; здесь — скалы`,kind:`verb`},{lesson:37,arabic:`تُرَاثٌ`,russian:`наследство, наследуемое имущество`,kind:`noun`},{lesson:37,arabic:`أَكْلًا لَمًّا`,russian:`поглощая без разбора, соединяя дозволенное и запретное`,kind:`expression`},{lesson:37,arabic:`ثَلْجُ الْيَقِينِ`,russian:`успокоение и внутренняя прохлада, которые даёт убеждённость`,kind:`expression`},{lesson:37,arabic:`شَفِيرٌ`,russian:`край, кромка; здесь — край могилы`,kind:`noun`},{lesson:38,arabic:`الْغَاشِيَةُ`,russian:`«покрывающая»; Судный день, охватывающий людей своими ужасами`,kind:`term`},{lesson:38,arabic:`حَدُورٌ`,russian:`крутой спуск`,kind:`noun`},{lesson:38,arabic:`وَاصِبٌ`,russian:`непрерывный, постоянный`,kind:`adjective`},{lesson:38,arabic:`ضَرِيعٌ`,russian:`сухое колючее растение; названная в аяте пища обитателей Ада`,kind:`noun`},{lesson:38,arabic:`شِبْرِقٌ`,russian:`колючее растение, после высыхания называемое ضَرِيعٌ`,kind:`noun`},{lesson:38,arabic:`غِسْلِينٌ`,russian:`выделения и гной; пища обитателей Ада`,kind:`noun`},{lesson:38,arabic:`عَازَّ – يُعَازُّ`,russian:`сопротивляться, противиться`,kind:`verb`},{lesson:38,arabic:`شَاحِطٌ`,russian:`далёкий, удалённый`,kind:`adjective`},{lesson:39,arabic:`غُثَاءٌ`,russian:`сухой растительный сор, остатки травы`,kind:`noun`},{lesson:39,arabic:`أَحْوَى`,russian:`тёмный, черноватый`,kind:`adjective`},{lesson:40,arabic:`الطَّارِقُ`,russian:`«приходящий ночью»; здесь — звезда`,kind:`term`},{lesson:40,arabic:`دَفَقَ – يَدْفُقُ`,russian:`излить сильной струёй; излиться`,kind:`verb`},{lesson:40,arabic:`تَرِيبَةٌ ج تَرَائِبُ`,russian:`кости верхней части груди, где находится ожерелье`,kind:`noun`},{lesson:40,arabic:`رَجْعٌ`,russian:`дождь, который вновь и вновь возвращается; не «возвращение» вообще`,kind:`noun`},{lesson:40,arabic:`رَادَ – يَرُودُ`,russian:`слабо двигаться; здесь — о ветре`,kind:`verb`},{lesson:40,arabic:`رَوْدٌ`,russian:`слабое движение ветра`,kind:`masdar`},{lesson:41,arabic:`أُخْدُودٌ`,russian:`глубокий ров, большая борозда в земле`,kind:`noun`},{lesson:41,arabic:`أَكْمَهُ`,russian:`слепой от рождения`,kind:`adjective`},{lesson:41,arabic:`قَرْقُورٌ`,russian:`большой корабль`,kind:`noun`},{lesson:41,arabic:`لَجَّجَ – يُلَجِّجُ بِـ`,russian:`увезти в открытое море, в морскую глубину`,kind:`verb`},{lesson:41,arabic:`اِنْكَفَأَ – يَنْكَفِئُ`,russian:`опрокинуться, перевернуться`,kind:`verb`},{lesson:41,arabic:`تَقَاعَسَ – يَتَقَاعَسُ`,russian:`замешкаться, попятиться, не решиться`,kind:`verb`},{lesson:41,arabic:`كِنَانَةٌ`,russian:`колчан, футляр для стрел`,kind:`noun`},{lesson:41,arabic:`فَتَنَ – يَفْتِنُ`,russian:`пытать, подвергать огненной пытке; значение в рассказе об обитателях рва`,kind:`verb`},{lesson:41,arabic:`قَدَّ – يَقُدُّ`,russian:`разрезать, рассечь; позднее в рассказе о Юсуфе — разорвать вдоль`,kind:`verb`},{lesson:41,arabic:`رَجَفَ – يَرْجُفُ`,russian:`сильно содрогаться, сотрясаться`,kind:`verb`},{lesson:42,arabic:`أَذِنَ – يَأْذَنُ لِـ`,russian:`прислушаться и повиноваться; не «разрешить»`,kind:`verb`},{lesson:42,arabic:`أَمْتٌ`,russian:`неровность, возвышение поверхности земли`,kind:`noun`},{lesson:42,arabic:`كَدَحَ – يَكْدَحُ`,russian:`усердно трудиться, изнурять себя трудом`,kind:`verb`},{lesson:42,arabic:`كَدْحٌ`,russian:`изнурительный труд, напряжённое стремление`,kind:`masdar`},{lesson:42,arabic:`حَارَ – يَحُورُ`,russian:`вернуться; не «растеряться»`,kind:`verb`},{lesson:42,arabic:`وَسَقَ – يَسِقُ`,russian:`собрать, соединить`,kind:`verb`},{lesson:42,arabic:`وَسْقٌ`,russian:`собирание, соединение; не мера зерна`,kind:`masdar`},{lesson:42,arabic:`اِتَّسَقَ – يَتَّسِقُ`,russian:`собраться в полноту; здесь — о полной луне`,kind:`verb`},{lesson:42,arabic:`طَبَقًا عَنْ طَبَقٍ`,russian:`переходя из одного состояния в другое, от одного испытания к следующему`,kind:`expression`},{lesson:43,arabic:`سِجِّينٌ`,russian:`Сиджжин; у автора — свод записанных злых деяний`,kind:`term`},{lesson:43,arabic:`رَانَ – يَرِينُ عَلَى`,russian:`покрыть, затмить; здесь — о грехах, покрывающих сердце`,kind:`verb`},{lesson:43,arabic:`رَيْنٌ`,russian:`покров грехов на сердце, его духовное омрачение`,kind:`masdar`},{lesson:43,arabic:`عِلِّيُّونَ`,russian:`‘Иллийюн; у автора — свод записанных благих деяний`,kind:`term`},{lesson:43,arabic:`رَحِيقٌ`,russian:`чистый, не смешанный с примесями напиток`,kind:`noun`},{lesson:43,arabic:`تَسْنِيمٌ`,russian:`Тасним; название источника в Раю`,kind:`term`},{lesson:43,arabic:`تَغَامَزَ – يَتَغَامَزُ`,russian:`обмениваться насмешливыми подмигиваниями`,kind:`verb`},{lesson:43,arabic:`ثَوَّبَ – يُثَوِّبُ`,russian:`воздать, отплатить; здесь — наказать за насмешки`,kind:`verb`},{lesson:43,arabic:`أُحْدُوثَةٌ`,russian:`рассказ о необычном событии, предмет пересудов`,kind:`noun`},{lesson:43,arabic:`نَحِيبٌ`,russian:`громкий плач, рыдание`,kind:`masdar`},{lesson:43,arabic:`حَجَلَةٌ ج حِجَالٌ`,russian:`полог, закрывающее ложе пространство`,kind:`noun`},{lesson:44,arabic:`اِنْفَطَرَ – يَنْفَطِرُ`,russian:`расколоться, разверзнуться`,kind:`verb`},{lesson:44,arabic:`بَعْثَرَ – يُبَعْثِرُ`,russian:`раскопать, переворошить, извлечь скрытое`,kind:`verb`},{lesson:45,arabic:`كَوَّرَ – يُكَوِّرُ`,russian:`свернуть, смотать; здесь — погасить солнце, свернув его свет`,kind:`verb`},{lesson:45,arabic:`اِنْكَدَرَ – يَنْكَدِرُ`,russian:`осыпаться, упасть; здесь — о звёздах`,kind:`verb`},{lesson:45,arabic:`عُشَرَاءُ ج عِشَارٌ`,russian:`верблюдица на десятом месяце беременности`,kind:`noun`},{lesson:45,arabic:`سَجَرَ – يَسْجُرُ`,russian:`наполнить топливом, разжечь; здесь — наполнить моря огнём`,kind:`verb`},{lesson:45,arabic:`وَأَدَ – يَئِدُ`,russian:`зарыть живым; прежде всего — новорождённую девочку`,kind:`verb`},{lesson:45,arabic:`وَأْدٌ`,russian:`закапывание живой новорождённой девочки`,kind:`masdar`},{lesson:45,arabic:`كَشَطَ – يَكْشِطُ`,russian:`снять, содрать покрытие`,kind:`verb`},{lesson:45,arabic:`كَنَسَ – يَكْنِسُ`,russian:`скрыться в логове; не «мести»`,kind:`verb`},{lesson:45,arabic:`كِنَاسٌ`,russian:`убежище дикого животного, логово`,kind:`noun`},{lesson:45,arabic:`كُنُوسٌ`,russian:`уход в убежище, исчезновение из виду`,kind:`masdar`},{lesson:45,arabic:`عَسْعَسَ – يُعَسْعِسُ`,russian:`наступать или отступать; о ночи — слово с противоположными значениями`,kind:`verb`},{lesson:45,arabic:`ضَنِينٌ`,russian:`скупой, не желающий поделиться`,kind:`adjective`},{lesson:45,arabic:`ظِنَّةٌ`,russian:`подозрение, обвинение`,kind:`noun`},{lesson:45,arabic:`طَالِحٌ`,russian:`дурной, нечестивый`,kind:`adjective`},{lesson:45,arabic:`دُرِّيٌّ ج دَرَارِيُّ`,russian:`ярко сияющая звезда; здесь — пять видимых планет`,kind:`noun`},{lesson:46,arabic:`كَلَحَ – يَكْلَحُ`,russian:`насупиться, нахмуриться`,kind:`verb`},{lesson:46,arabic:`كَبْوَةٌ`,russian:`спотыкание, падение`,kind:`noun`},{lesson:46,arabic:`سَافِرٌ ج سَفَرَةٌ`,russian:`писец; здесь — ангел, переписывающий Писание`,kind:`term`},{lesson:46,arabic:`أَقْبَرَ – يُقْبِرُ`,russian:`дать возможность похоронить, устроить погребение; отличать от قَبَرَ «похоронить»`,kind:`verb`},{lesson:46,arabic:`أَنْشَرَ – يُنْشِرُ`,russian:`воскресить, оживить после смерти`,kind:`verb`},{lesson:46,arabic:`قَضْبٌ`,russian:`свежескошенная зелень, зелёный корм`,kind:`noun`},{lesson:46,arabic:`قَضَبَ – يَقْضِبُ`,russian:`срезать, скашивать`,kind:`verb`},{lesson:46,arabic:`أَبٌّ`,russian:`трава, пастбищный корм`,kind:`noun`},{lesson:46,arabic:`الصَّاخَّةُ`,russian:`оглушающий крик Судного дня`,kind:`term`},{lesson:46,arabic:`صَخَّ – يَصُخُّ`,russian:`оглушить сильным звуком`,kind:`verb`},{lesson:46,arabic:`قَتَرَةٌ`,russian:`чернота, похожая на дым, покрывающая лицо`,kind:`noun`},{lesson:47,arabic:`نَشْطٌ`,russian:`вытягивание, извлечение; не «бодрость»`,kind:`masdar`},{lesson:47,arabic:`رَجْفٌ`,russian:`сильное сотрясение, колебание`,kind:`masdar`},{lesson:47,arabic:`الرَّاجِفَةُ`,russian:`первое трубление, от которого земля содрогнётся`,kind:`term`},{lesson:47,arabic:`الرَّادِفَةُ`,russian:`второе трубление, следующее за первым и возвещающее воскресение`,kind:`term`},{lesson:47,arabic:`وَجَفَ – يَجِفُ`,russian:`сильно биться, трепетать; о сердце`,kind:`verb`},{lesson:47,arabic:`وَجِيفٌ`,russian:`сильное биение, трепет`,kind:`masdar`},{lesson:47,arabic:`وَجِيبٌ`,russian:`сердцебиение, сильное биение сердца`,kind:`masdar`},{lesson:47,arabic:`رَجَعَ إِلَى حَافِرَتِهِ`,russian:`вернулся в первоначальное состояние, к тому, с чего начал`,kind:`expression`},{lesson:47,arabic:`نَخِرَ – يَنْخَرُ`,russian:`истлеть, стать трухлявым; о кости`,kind:`verb`},{lesson:47,arabic:`السَّاهِرَةُ`,russian:`поверхность земли; место, где окажутся воскресшие`,kind:`term`},{lesson:47,arabic:`أَغْطَشَ – يُغْطِشُ`,russian:`покрыть мраком, сделать тёмным`,kind:`verb`},{lesson:47,arabic:`الطَّامَّةُ الْكُبْرَى`,russian:`величайшее бедствие; Судный день или второе трубление`,kind:`term`},{lesson:48,arabic:`وَهَّاجٌ`,russian:`ярко сияющий и жаркий`,kind:`adjective`},{lesson:48,arabic:`الْمُعْصِرَاتُ`,russian:`тучи, готовые пролиться дождём; в другом толковании — ветры`,kind:`noun`},{lesson:48,arabic:`ثَجَّ – يَثُجُّ`,russian:`лить обильно`,kind:`verb`},{lesson:48,arabic:`ثَجَّاجٌ`,russian:`обильно льющийся; о дожде`,kind:`adjective`},{lesson:48,arabic:`أَلْفَافٌ`,russian:`густо переплетающиеся; здесь — густые сады`,kind:`adjective`},{lesson:48,arabic:`غَسَّاقٌ`,russian:`гнойные выделения обитателей Ада`,kind:`noun`},{lesson:48,arabic:`كَاعِبٌ ج كَوَاعِبُ`,russian:`девушка с округлившейся грудью`,kind:`noun`},{lesson:48,arabic:`تِرْبٌ ج أَتْرَابٌ`,russian:`ровесник, ровесница`,kind:`noun`},{lesson:48,arabic:`دِهَاقٌ`,russian:`полный до краёв; о чаше`,kind:`adjective`},{lesson:48,arabic:`عَطَاءً حِسَابًا`,russian:`обильный, достаточный дар; حِسَاب здесь означает «достаточный», а не «расчёт»`,kind:`expression`},{lesson:48,arabic:`مَادَ – يَمِيدُ`,russian:`колебаться, качаться; здесь — о земле`,kind:`verb`},{lesson:49,arabic:`فَطْرٌ ج فُطُورٌ`,russian:`трещина, разрыв`,kind:`noun`},{lesson:49,arabic:`حَسِيرٌ`,russian:`утомлённый, изнурённый; здесь — о зрении`,kind:`adjective`},{lesson:49,arabic:`خَبَلَ – يَخْبِلُ`,russian:`повредить разум, лишить рассудка`,kind:`verb`},{lesson:50,arabic:`شَهِيقٌ`,russian:`резкий протяжный звук, подобный крику осла`,kind:`noun`},{lesson:50,arabic:`مَنْكِبٌ ج مَنَاكِبُ`,russian:`сторона, край, возвышенность земли; не «плечо»`,kind:`noun`},{lesson:51,arabic:`مَارَ – يَمُورُ`,russian:`бурно колебаться, ходить ходуном`,kind:`verb`},{lesson:51,arabic:`حَاصِبٌ`,russian:`буря, несущая камни; каменная осыпь как наказание`,kind:`noun`},{lesson:51,arabic:`نَكِيرٌ`,russian:`осуждение, наказание за отвергнутую истину`,kind:`noun`},{lesson:51,arabic:`شَرَادٌ`,russian:`бегство, отвращение и уклонение`,kind:`masdar`},{lesson:51,arabic:`أَكَبَّ – يُكِبُّ`,russian:`упасть лицом вниз; не أَكَبَّ عَلَى «увлечённо заняться»`,kind:`verb`},{lesson:51,arabic:`زُلْفَةٌ`,russian:`близость, близкое расстояние`,kind:`noun`},{lesson:51,arabic:`غَوْرٌ`,russian:`уход воды глубоко под землю, где её не достать`,kind:`masdar`},{lesson:51,arabic:`مَعِينٌ`,russian:`текущая, доступная вода`,kind:`adjective`},{lesson:51,arabic:`عُثُورٌ`,russian:`спотыкание`,kind:`masdar`},{lesson:52,arabic:`الْوَاقِعَةُ`,russian:`«неизбежно наступающая»; Судный день`,kind:`term`},{lesson:52,arabic:`رَجَّ – يَرُجُّ`,russian:`сильно сотрясти`,kind:`verb`},{lesson:52,arabic:`رَجٌّ`,russian:`сильное сотрясение`,kind:`masdar`},{lesson:52,arabic:`بَسَّ – يَبُسُّ`,russian:`растереть, раздробить; также — погнать`,kind:`verb`},{lesson:52,arabic:`بَسٌّ`,russian:`дробление, растирание; также — прогон`,kind:`masdar`},{lesson:52,arabic:`ثُلَّةٌ`,russian:`большая группа людей`,kind:`noun`},{lesson:52,arabic:`وَضَنَ – يَضِنُ`,russian:`сплести, соединить плетением`,kind:`verb`},{lesson:52,arabic:`خُلْدَةٌ`,russian:`серьга; не «вечность»`,kind:`noun`},{lesson:52,arabic:`أَنْزَفَ – يُنْزِفُ`,russian:`исчерпать запас напитка; о людях — остаться без вина`,kind:`verb`},{lesson:52,arabic:`قِيلٌ`,russian:`речь, высказывание`,kind:`masdar`},{lesson:52,arabic:`هَذَيَانٌ`,russian:`бред, бессвязная речь`,kind:`masdar`},{lesson:52,arabic:`نَزَفَ – يَنْزِفُ`,russian:`лишить рассудка; в тексте страдательная форма: потерять рассудок от опьянения`,kind:`verb`},{lesson:53,arabic:`خَضَدَ – يَخْضِدُ`,russian:`срезать, удалить шипы`,kind:`verb`},{lesson:53,arabic:`طَلْحٌ`,russian:`у автора — банановое дерево`,kind:`noun`},{lesson:53,arabic:`عَرُوبٌ ج عُرُبٌ`,russian:`женщина, нежно любящая мужа и расположенная к нему`,kind:`noun`},{lesson:53,arabic:`يَحْمُومٌ`,russian:`густой чёрный дым`,kind:`noun`},{lesson:53,arabic:`الْحِنْثُ الْعَظِيمُ`,russian:`великий грех; здесь — многобожие или отрицание воскресения`,kind:`term`},{lesson:53,arabic:`أَهْيَمُ ج هِيمٌ`,russian:`верблюд с неутолимой жаждой`,kind:`adjective`},{lesson:54,arabic:`تَفَكَّهَ – يَتَفَكَّهُ`,russian:`изумляться или сожалеть; не «наслаждаться»`,kind:`verb`},{lesson:54,arabic:`غَرَامٌ`,russian:`гибель, неотступное бедствие; не «любовь»`,kind:`noun`},{lesson:54,arabic:`طَرُوقَةٌ`,russian:`самка, предназначенная для спаривания`,kind:`noun`},{lesson:54,arabic:`قَوَاءٌ`,russian:`безлюдная пустынная местность`,kind:`noun`},{lesson:54,arabic:`أَقْوَى – يُقْوِي`,russian:`оказаться в пустыне; остаться без припасов; опустеть — о жилище`,kind:`verb`},{lesson:54,arabic:`مُحَارَفٌ`,russian:`неудачливый в добывании пропитания`,kind:`adjective`},{lesson:54,arabic:`بَخْتٌ`,russian:`удача, счастливый удел`,kind:`noun`},{lesson:55,arabic:`التَّنْزِيلُ`,russian:`ниспосланное Писание, Коран; не процесс ниспослания`,kind:`term`},{lesson:55,arabic:`دَانَ – يَدِينُ`,russian:`владычествовать, управлять подданными; не «исповедовать религию»`,kind:`verb`},{lesson:55,arabic:`رَيْحَانٌ`,russian:`удел, пропитание; не только душистое растение`,kind:`noun`},{lesson:55,arabic:`حَقُّ الْيَقِينِ`,russian:`достоверная истина, не оставляющая сомнений`,kind:`term`},{lesson:56,arabic:`فَتَاحَةٌ`,russian:`судебное решение, рассуживание спора`,kind:`noun`},{lesson:56,arabic:`بَهِيتَةٌ`,russian:`клевета, ложное обвинение`,kind:`noun`},{lesson:56,arabic:`دَائِرَةُ السَّوْءِ`,russian:`бедствие, оборачивающееся против человека; гибельный поворот судьбы`,kind:`expression`},{lesson:57,arabic:`عَزَّرَ – يُعَزِّرُ`,russian:`поддерживать, укреплять, помогать; не «подвергать та‘зиру»`,kind:`verb`},{lesson:57,arabic:`سُبْحَةٌ`,russian:`добровольная молитва; не «чётки»`,kind:`noun`},{lesson:57,arabic:`بَارَ – يَبُورُ`,russian:`погибнуть, оказаться негодным`,kind:`verb`},{lesson:57,arabic:`بُورٌ`,russian:`погибшие, негодные; о людях без добра`,kind:`adjective`},{lesson:58,arabic:`نَاجَزَ – يُنَاجِزُ`,russian:`вступить в решающее сражение`,kind:`verb`},{lesson:58,arabic:`مَعَرَّةٌ`,russian:`вред, неприятность, тяжёлое последствие поступка`,kind:`noun`},{lesson:58,arabic:`عَرَّ – يَعُرُّ`,russian:`поразить неприятностью, причинить вред`,kind:`verb`},{lesson:58,arabic:`تَزَيَّلَ – يَتَزَيَّلُ`,russian:`разойтись, отделиться друг от друга`,kind:`verb`},{lesson:58,arabic:`حَمِيَّةُ الْجَاهِلِيَّةِ`,russian:`горделивая ревность и упрямство языческого неведения`,kind:`expression`},{lesson:58,arabic:`كَلِمَةُ التَّقْوَى`,russian:`«слово богобоязненности»; у автора прежде всего — свидетельство единобожия`,kind:`term`},{lesson:59,arabic:`شَطْءٌ`,russian:`новый побег растения, боковой отросток`,kind:`noun`},{lesson:59,arabic:`أَشْطَأَ – يُشْطِئُ`,russian:`выпустить побеги; о растении`,kind:`verb`},{lesson:59,arabic:`آزَرَ – يُؤَازِرُ`,russian:`укрепить, поддержать`,kind:`verb`},{lesson:59,arabic:`اِسْتَغْلَظَ – يَسْتَغْلِظُ`,russian:`стать толстым, окрепнуть`,kind:`verb`},{lesson:60,arabic:`قَمَحَ – يَقْمَحُ`,russian:`поднять голову, не опуская её; о напившемся верблюде`,kind:`verb`},{lesson:60,arabic:`أَقْمَحَ – يُقْمِحُ`,russian:`заставить держать голову поднятой, не давая опустить её`,kind:`verb`},{lesson:60,arabic:`رَضَخَ – يَرْضَخُ`,russian:`разбить, размозжить ударом; не «выдать небольшое вознаграждение»`,kind:`verb`},{lesson:60,arabic:`دَمَغَ – يَدْمَغُ`,russian:`разбить голову, поразить мозг`,kind:`verb`},{lesson:60,arabic:`إِمَامٌ مُبِينٌ`,russian:`ясный первообраз записей; здесь — Хранимая скрижаль`,kind:`term`},{lesson:60,arabic:`لَزَّ – يَلُزُّ`,russian:`плотно прижать, принудить давлением`,kind:`verb`},{lesson:61,arabic:`طَائِرٌ`,russian:`дурной знак, причина несчастья; здесь — неверие самих людей`,kind:`noun`},{lesson:62,arabic:`بَلَقٌ`,russian:`пестрина, сочетание белых и тёмных пятен`,kind:`noun`},{lesson:62,arabic:`بَهَقٌ`,russian:`светлые пятна на коже`,kind:`noun`},{lesson:62,arabic:`مَنَازِلُ الْقَمَرِ`,russian:`лунные стоянки, участки пути луны`,kind:`term`},{lesson:62,arabic:`اِسْتَقْوَسَ – يَسْتَقْوِسُ`,russian:`изогнуться дугой`,kind:`verb`},{lesson:62,arabic:`عُرْجُونٌ`,russian:`изогнутая высохшая ножка пальмовой кисти`,kind:`noun`},{lesson:62,arabic:`شِمْرَاخٌ`,russian:`веточка пальмовой кисти, несущая плоды`,kind:`noun`},{lesson:62,arabic:`صَرِيخٌ`,russian:`помощник, приходящий на зов о спасении; также — сама помощь`,kind:`noun`},{lesson:64,arabic:`جِبِلٌّ`,russian:`большое множество созданий, многочисленный народ`,kind:`noun`},{lesson:64,arabic:`مَكَانَةٌ`,russian:`место, местонахождение; не «высокое положение»`,kind:`noun`},{lesson:64,arabic:`نَكَّسَ – يُنَكِّسُ`,russian:`обратить вспять, перевернуть; здесь — вернуть силу и разум человека к слабости`,kind:`verb`},{lesson:65,arabic:`مَرْخٌ`,russian:`дерево, из древесины которого добывают огонь трением`,kind:`noun`},{lesson:65,arabic:`عَفَارٌ`,russian:`дерево, древесину которого используют для добывания огня`,kind:`noun`},{lesson:65,arabic:`وَرْيٌ`,russian:`высекание и появление огня`,kind:`masdar`},{lesson:65,arabic:`اِسْتَمْجَدَ – يَسْتَمْجِدُ`,russian:`превосходить обилием; здесь — давать особенно много огня`,kind:`verb`},{lesson:65,arabic:`اِنْقَشَعَ – يَنْقَشِعُ`,russian:`рассеяться, исчезнуть; о тучах, тревоге`,kind:`verb`},{lesson:67,arabic:`طَرِيقَةٌ ج طَرَائِقُ`,russian:`небесный слой, небо; не «способ» или «путь»`,kind:`noun`},{lesson:67,arabic:`اِسْتَأْدَى – يَسْتَأْدِي`,russian:`потребовать исполнения, уплаты или отдачи должного`,kind:`verb`},{lesson:67,arabic:`صِبْغٌ`,russian:`приправа, то, во что макают пищу; здесь — оливковое масло`,kind:`noun`},{lesson:68,arabic:`جِنَّةٌ`,russian:`безумие; не جَنَّةٌ «сад» и не جِنَّةٌ «джинны» как собирательное имя`,kind:`noun`},{lesson:68,arabic:`سَلْوَةٌ`,russian:`утешение, облегчение горя`,kind:`noun`},{lesson:68,arabic:`تَرَأَّسَ – يَتَرَأَّسُ`,russian:`встать во главе, стать руководителем`,kind:`verb`},{lesson:68,arabic:`كَلَأَ – يَكْلَأُ`,russian:`охранять, оберегать`,kind:`verb`},{lesson:68,arabic:`كِلَاءَةٌ`,russian:`охрана, оберегание`,kind:`masdar`},{lesson:69,arabic:`تَتْرَى`,russian:`один за другим, последовательно`,kind:`adverb`},{lesson:69,arabic:`رَبْوَةٌ`,russian:`возвышенность, приподнятое место`,kind:`noun`},{lesson:69,arabic:`عَانَ – يَعِينُ`,russian:`увидеть, воспринять глазом`,kind:`verb`},{lesson:69,arabic:`أُمَّةٌ`,russian:`религия, вероисповедание; не «народ»`,kind:`noun`},{lesson:69,arabic:`حَمِيلُ السَّيْلِ`,russian:`сор, который несёт поток воды`,kind:`expression`},{lesson:69,arabic:`أَرْطَى`,russian:`пустынный кустарник арта; в грамматическом примере`,kind:`noun`},{lesson:70,arabic:`زُبْرَةٌ ج زُبَرٌ`,russian:`кусок, отдельная часть`,kind:`noun`},{lesson:70,arabic:`غَمْرَةٌ`,russian:`поглощающая небрежность, глубокая беспечность`,kind:`noun`},{lesson:70,arabic:`جَأَرَ – يَجْأَرُ`,russian:`громко взывать о помощи, вопить`,kind:`verb`},{lesson:70,arabic:`جُؤَارٌ`,russian:`громкий крик о помощи`,kind:`masdar`},{lesson:70,arabic:`نَكَصَ – يَنْكِصُ`,russian:`попятиться, отступить назад`,kind:`verb`},{lesson:70,arabic:`نُكُوصٌ`,russian:`отступление назад, движение пятясь`,kind:`masdar`},{lesson:70,arabic:`هَجَرَ – يَهْجُرُ`,russian:`говорить бессвязно, бредить; не «оставить»`,kind:`verb`},{lesson:70,arabic:`هَجْرٌ`,russian:`бред, бессвязная речь; не «оставление»`,kind:`masdar`},{lesson:70,arabic:`أَهْجَرَ – يُهْجِرُ`,russian:`произносить непристойную, грубую речь`,kind:`verb`},{lesson:70,arabic:`أَبْلَجُ`,russian:`ясный, очевидный; о доводе и истине`,kind:`adjective`},{lesson:70,arabic:`خَرْجٌ`,russian:`плата, вознаграждение за услугу`,kind:`noun`},{lesson:70,arabic:`عِلْهِزٌ`,russian:`голодная пища из смешанных крови и шерсти, описанная в тексте`,kind:`noun`},{lesson:70,arabic:`اِسْتَكَانَ – يَسْتَكِينُ`,russian:`смириться, покорно склониться`,kind:`verb`},{lesson:70,arabic:`شَكِيمَةٌ`,russian:`твёрдость характера, непреклонность; буквально — часть удила`,kind:`noun`},{lesson:70,arabic:`اِسْتَبْدَعَ – يَسْتَبْدِعُ`,russian:`посчитать необычным, неслыханным`,kind:`verb`},{lesson:70,arabic:`أَبْلَسَ – يُبْلِسُ`,russian:`отчаяться, оцепенеть от безнадёжности`,kind:`verb`},{lesson:70,arabic:`مَقَادَةٌ`,russian:`покорность, податливость`,kind:`masdar`},{lesson:71,arabic:`مَزْلَفَةٌ ج مَزَالِفُ`,russian:`селение, населённое место; в приведённом стихе`,kind:`noun`},{lesson:72,arabic:`هَمْزَةٌ ج هَمَزَاتٌ`,russian:`толчок, укол; переносно — побуждение шайтана к греху`,kind:`noun`},{lesson:72,arabic:`مِهْمَازٌ`,russian:`шпора, которой подгоняют животное`,kind:`noun`},{lesson:72,arabic:`نَخْسٌ`,russian:`укол, подталкивание`,kind:`masdar`},{lesson:72,arabic:`ثَلْمٌ`,russian:`брешь, повреждение; здесь — ущерб религии`,kind:`masdar`},{lesson:72,arabic:`اِسْتَزَلَّ – يَسْتَزِلُّ`,russian:`заставить оступиться, увлечь к ошибке`,kind:`verb`},{lesson:73,arabic:`لَفَحَ – يَلْفَحُ`,russian:`обжечь сильным жаром`,kind:`verb`},{lesson:73,arabic:`شِقْوَةٌ`,russian:`несчастье, обречённость на несчастную участь`,kind:`masdar`},{lesson:73,arabic:`سِخْرِيٌّ / سُخْرِيٌّ`,russian:`осмеяние; предмет насмешки`,kind:`noun`},{lesson:73,arabic:`اِسْتَقْصَرَ – يَسْتَقْصِرُ`,russian:`посчитать коротким или недостаточным`,kind:`verb`},{lesson:74,arabic:`عِوَجٌ`,russian:`кривизна в смысле, отклонение или противоречие в рассуждении`,kind:`noun`},{lesson:74,arabic:`عَوَجٌ`,russian:`физическая кривизна предмета; отличать от عِوَجٌ`,kind:`noun`},{lesson:74,arabic:`بَخَعَ – يَبْخَعُ`,russian:`погубить, изнурить себя от горя`,kind:`verb`},{lesson:74,arabic:`جُرُزٌ`,russian:`сухая, лишённая растительности земля`,kind:`adjective`},{lesson:75,arabic:`ضَرَبَ – يَضْرِبُ عَلَى الْآذَانِ`,russian:`погрузить в глубокий сон, не давая слышать`,kind:`verb`},{lesson:75,arabic:`بَعَثَ – يَبْعَثُ`,russian:`разбудить, пробудить от сна; не «отправить»`,kind:`verb`},{lesson:75,arabic:`الْفُتُوَّةُ`,russian:`благородство: щедрость, отказ от причинения вреда и жалоб`,kind:`term`},{lesson:75,arabic:`رَبَطَ – يَرْبِطُ عَلَى الْقَلْبِ`,russian:`укрепить сердце, дать стойкость`,kind:`verb`},{lesson:75,arabic:`شَطَطٌ`,russian:`крайняя несправедливость, чрезмерное отклонение от истины`,kind:`noun`},{lesson:75,arabic:`شَطَّ – يَشُطُّ`,russian:`далеко отойти, удалиться`,kind:`verb`},{lesson:75,arabic:`مِرْفَقٌ / مَرْفِقٌ`,russian:`то, чем пользуются; помощь, полезное средство; не «локоть»`,kind:`noun`},{lesson:75,arabic:`تَزَاوَرَ – يَتَزَاوَرُ`,russian:`отклоняться, уходить в сторону; не «навещать друг друга»`,kind:`verb`},{lesson:75,arabic:`اِزْوَرَّ – يَزْوَرُّ`,russian:`отклониться, повернуться в сторону`,kind:`verb`},{lesson:75,arabic:`قَرَضَ – يَقْرِضُ`,russian:`миновать, оставить в стороне; здесь — о лучах солнца`,kind:`verb`},{lesson:75,arabic:`فَجْوَةٌ`,russian:`широкое свободное пространство, открытое место`,kind:`noun`},{lesson:75,arabic:`وَصِيدٌ`,russian:`вход, порог; пространство перед входом`,kind:`noun`},{lesson:75,arabic:`وَرِقٌ`,russian:`серебро, серебряные деньги; не وَرَقٌ «лист»`,kind:`noun`},{lesson:75,arabic:`أَعْثَرَ – يُعْثِرُ عَلَى`,russian:`дать обнаружить, сделать известным`,kind:`verb`},{lesson:75,arabic:`يَعْقُوبِيٌّ`,russian:`принадлежащий к яковитской христианской традиции`,kind:`term`},{lesson:75,arabic:`نَسْطُورِيٌّ`,russian:`принадлежащий к несторианской христианской традиции`,kind:`term`},{lesson:75,arabic:`رَجْمًا بِالْغَيْبِ`,russian:`наугад, строя догадки о неизвестном`,kind:`expression`},{lesson:75,arabic:`نُصُوعٌ`,russian:`чистота, ясность, отсутствие примеси`,kind:`masdar`},{lesson:76,arabic:`مُلْتَحَدٌ`,russian:`убежище, место, куда можно уклониться`,kind:`noun`},{lesson:76,arabic:`نَبَا – يَنْبُو عَنْ`,russian:`отвернуться, не задержаться; здесь — об отведённом взгляде`,kind:`verb`},{lesson:76,arabic:`فُرُطٌ`,russian:`выходящий за пределы истины, чрезмерный`,kind:`adjective`},{lesson:76,arabic:`سُرَادِقٌ`,russian:`ограждение вокруг шатра; здесь — сплошное огненное или дымовое окружение`,kind:`noun`},{lesson:76,arabic:`مُهْلٌ`,russian:`расплавленный металл или густой масляный осадок`,kind:`noun`},{lesson:76,arabic:`دُرْدِيٌّ`,russian:`густой осадок на дне масла или напитка`,kind:`noun`},{lesson:76,arabic:`مُرْتَفَقٌ`,russian:`место отдыха и опоры, удобное пристанище`,kind:`noun`},{lesson:76,arabic:`سُنْدُسٌ`,russian:`тонкий шёлк`,kind:`noun`},{lesson:76,arabic:`إِسْتَبْرَقٌ`,russian:`толстая шёлковая ткань, парча`,kind:`noun`},{lesson:76,arabic:`اِنْشَوَى – يَنْشَوِي`,russian:`обжечься, стать обожжённым`,kind:`verb`},{lesson:77,arabic:`ثَمَرٌ / ثُمُرٌ`,russian:`разные виды имущества и богатства; не только «плоды»`,kind:`noun`},{lesson:77,arabic:`بَادَ – يَبِيدُ`,russian:`погибнуть, исчезнуть`,kind:`verb`},{lesson:77,arabic:`بَيْدُودَةٌ`,russian:`гибель, исчезновение`,kind:`masdar`},{lesson:77,arabic:`حُسْبَانٌ`,russian:`кара, губительное бедствие с неба; не «расчёт»`,kind:`noun`},{lesson:77,arabic:`زَلَقٌ`,russian:`скользкий, гладкий; о земле`,kind:`adjective`},{lesson:77,arabic:`خَاوِيَةٌ عَلَى عُرُوشِهَا`,russian:`обрушившаяся на свои опоры, полностью разрушенная`,kind:`expression`},{lesson:77,arabic:`دِهْقَانٌ ج دَهَاقِينُ`,russian:`землевладелец, хозяин сельского хозяйства`,kind:`noun`},{lesson:78,arabic:`غَدَارَةٌ`,russian:`оставленный остаток`,kind:`noun`},{lesson:78,arabic:`عَضُدٌ`,russian:`помощь, опора; не «верхняя часть руки»`,kind:`noun`},{lesson:78,arabic:`مَوْبِقٌ`,russian:`место гибели, погибель`,kind:`noun`},{lesson:78,arabic:`وَبَقَ – يَبِقُ`,russian:`погибнуть`,kind:`verb`},{lesson:78,arabic:`وُبُوقٌ`,russian:`гибель`,kind:`masdar`},{lesson:78,arabic:`قُبُلًا`,russian:`разными видами, один за другим; в этой огласовке — множественное число قَبِيلٌ`,kind:`adverb`},{lesson:78,arabic:`قِبَلًا`,russian:`воочию, непосредственно перед глазами; отличать от قُبُلًا`,kind:`adverb`},{lesson:78,arabic:`وَقْرٌ`,russian:`тяжесть, глухота; не وِقْرٌ «груз»`,kind:`noun`},{lesson:78,arabic:`مَوْئِلٌ`,russian:`убежище, место спасения`,kind:`noun`},{lesson:78,arabic:`وَأَلَ – يَئِلُ`,russian:`найти спасение, укрыться`,kind:`verb`},{lesson:79,arabic:`سَرَبٌ`,russian:`скрытый проход, путь; здесь — путь рыбы в море`,kind:`noun`},{lesson:79,arabic:`سَرَبَ – يَسْرُبُ`,russian:`пройти, скрыться, проникнуть в потайной проход`,kind:`verb`},{lesson:79,arabic:`قَصَصٌ`,russian:`следование по следам; не «рассказы»`,kind:`masdar`},{lesson:79,arabic:`الْعِلْمُ اللَّدُنِّيُّ`,russian:`знание, полученное через внушение, а не обычное обучение`,kind:`term`},{lesson:79,arabic:`خُبْرٌ`,russian:`глубокое знание, осведомлённость; не خَبَرٌ «сообщение»`,kind:`noun`},{lesson:79,arabic:`إِمْرٌ`,russian:`великий, тяжёлый и необычный поступок`,kind:`noun`},{lesson:79,arabic:`نُكْرٌ`,russian:`предосудительное, ужасное действие`,kind:`noun`},{lesson:79,arabic:`غَضَاضَةٌ`,russian:`унижение, умаление достоинства`,kind:`noun`},{lesson:79,arabic:`اِسْتَطْعَمَ – يَسْتَطْعِمُ`,russian:`попросить накормить, попросить угощения`,kind:`verb`},{lesson:79,arabic:`اِسْتَضَافَ – يَسْتَضِيفُ`,russian:`попросить принять гостем`,kind:`verb`},{lesson:79,arabic:`أَمِرَ – يَأْمَرُ`,russian:`стать великим, усилиться; здесь — о тяжести или значительности дела`,kind:`verb`},{lesson:80,arabic:`حَمَأَةٌ`,russian:`чёрная грязь, ил`,kind:`noun`},{lesson:80,arabic:`حَمِئَ – يَحْمَأُ`,russian:`наполниться чёрным илом; о водоёме`,kind:`verb`},{lesson:80,arabic:`حَمِئٌ`,russian:`содержащий чёрный ил; не حَامٍ «горячий»`,kind:`adjective`},{lesson:80,arabic:`رَدْمٌ`,russian:`прочная засыпка или заграждение, более массивное, чем обычная преграда`,kind:`noun`},{lesson:80,arabic:`دَكَّاءُ`,russian:`сровненная с землёй, плоская`,kind:`adjective`},{lesson:80,arabic:`مِنْفَاخٌ ج مَنَافِيخُ`,russian:`кузнечные мехи`,kind:`noun`},{lesson:81,arabic:`صَدَفٌ`,russian:`боковая поверхность горы; не «раковина»`,kind:`noun`},{lesson:81,arabic:`قِطْرٌ`,russian:`расплавленная медь; не قَطْرٌ «капли»`,kind:`noun`},{lesson:81,arabic:`نَغَفٌ`,russian:`мелкие паразитические черви или личинки`,kind:`noun`},{lesson:81,arabic:`حَوْلٌ`,russian:`переход, перемещение; не «год»`,kind:`masdar`},{lesson:81,arabic:`مِدَادٌ`,russian:`чернила`,kind:`noun`},{lesson:81,arabic:`تَلَأْلَأَ – يَتَلَأْلَأُ`,russian:`ярко сиять, сверкать`,kind:`verb`},{lesson:82,arabic:`تَأْوِيلُ الْأَحَادِيثِ`,russian:`толкование сновидений; в другом объяснении — понимание речей пророков и Писаний`,kind:`term`},{lesson:82,arabic:`جَبَى – يَجْبِي`,russian:`собрать для себя, сосредоточить; здесь — собрать воду в водоём`,kind:`verb`},{lesson:82,arabic:`عَبَرَ – يَعْبُرُ الرُّؤْيَا`,russian:`истолковать сновидение; не «переправиться»`,kind:`verb`},{lesson:82,arabic:`عِبَارَةُ الرُّؤْيَا`,russian:`истолкование сновидения; عِبَارَة здесь — масдар عَبَرَ, а не «фраза» или «выражение»`,kind:`masdar`},{lesson:83,arabic:`غَيَابَةُ الْجُبِّ`,russian:`скрытая от глаз глубина колодца`,kind:`expression`},{lesson:83,arabic:`رَتْعَةٌ`,russian:`вольное, обильное питание`,kind:`noun`},{lesson:83,arabic:`اِرْتَعَى – يَرْتَعِي`,russian:`пастись, кормиться`,kind:`verb`},{lesson:83,arabic:`تَمِيمَةٌ`,russian:`амулет, предмет, подвешиваемый для защиты`,kind:`noun`},{lesson:83,arabic:`جَامٌ`,russian:`большая чаша`,kind:`noun`},{lesson:83,arabic:`صُوَاعٌ`,russian:`мера сыпучего; чаша, используемая как мера`,kind:`noun`},{lesson:83,arabic:`رُزْءٌ`,russian:`тяжёлая утрата, несчастье`,kind:`noun`},{lesson:84,arabic:`وَارِدٌ`,russian:`тот, кто первым идёт за водой для спутников; не «поступающий» и не «упомянутый»`,kind:`noun`},{lesson:84,arabic:`أَدْلَى – يُدْلِي`,russian:`опустить ведро в колодец`,kind:`verb`},{lesson:84,arabic:`بَضَعَ – يَبْضَعُ`,russian:`отрезать часть`,kind:`verb`},{lesson:84,arabic:`شَرَى – يَشْرِي`,russian:`продать; в другом толковании — купить; слово с противоположными значениями`,kind:`verb`},{lesson:84,arabic:`اِسْتَوْزَرَ – يَسْتَوْزِرُ`,russian:`назначить министром`,kind:`verb`},{lesson:84,arabic:`تَدَرَّبَ – يَتَدَرَّبُ`,russian:`обучиться на практике, освоиться с делом`,kind:`verb`},{lesson:85,arabic:`رَاوَدَ – يُرَاوِدُ عَنْ نَفْسِهِ`,russian:`добиваться любовной близости, пытаться соблазнить`,kind:`verb`},{lesson:85,arabic:`هَيْتَ لَكَ`,russian:`иди сюда, подойди; призыв к себе`,kind:`expression`},{lesson:85,arabic:`قَدٌّ`,russian:`продольный разрыв, разрез`,kind:`masdar`},{lesson:85,arabic:`فِرَاشُ الْقُفْلِ`,russian:`мелкие запирающие детали замка; не «постель»`,kind:`expression`},{lesson:85,arabic:`قُبُلٌ`,russian:`передняя сторона; не название полового органа`,kind:`noun`},{lesson:85,arabic:`دُبُرٌ`,russian:`задняя сторона, тыльная часть`,kind:`noun`},{lesson:85,arabic:`نَجَعَ – يَنْجَعُ`,russian:`оказаться действенным, подействовать`,kind:`verb`},{lesson:85,arabic:`بَرَّانِيٌّ`,russian:`внешний, наружный`,kind:`adjective`},{lesson:86,arabic:`شِغَافٌ`,russian:`оболочка сердца`,kind:`noun`},{lesson:86,arabic:`أَكْبَرَ – يُكْبِرُ`,russian:`вступить в возраст менструаций; о женщине, в одном из приведённых толкований`,kind:`verb`},{lesson:86,arabic:`عَاتِقٌ ج عَوَاتِقُ`,russian:`взрослая незамужняя девушка; не «плечо»`,kind:`noun`},{lesson:86,arabic:`حَاشَ لِلَّهِ`,russian:`Аллах пречист; выражение очищения от приписываемого и удивления`,kind:`expression`},{lesson:86,arabic:`اِسْتَعْصَمَ – يَسْتَعْصِمُ`,russian:`решительно удержаться, защитить себя от греха`,kind:`verb`},{lesson:86,arabic:`صَبَا – يَصْبُو إِلَى`,russian:`склоняться с влечением, испытывать влюблённость`,kind:`verb`},{lesson:86,arabic:`صَبْوَةٌ`,russian:`влечение, склонность к любви и страсти`,kind:`masdar`},{lesson:86,arabic:`الصَّبَا`,russian:`восточный ветер`,kind:`noun`},{lesson:86,arabic:`بَدَاءٌ`,russian:`возникновение нового мнения, обнаружившееся решение`,kind:`masdar`},{lesson:86,arabic:`اِسْتَكْتَمَ – يَسْتَكْتِمُ`,russian:`попросить или потребовать хранить тайну`,kind:`verb`},{lesson:86,arabic:`جَدْوَى`,russian:`польза, благотворный результат`,kind:`noun`},{lesson:86,arabic:`مِطْوَاعٌ`,russian:`очень покорный, легко подчиняющийся чужой воле`,kind:`adjective`},{lesson:87,arabic:`شَرَابِيٌّ`,russian:`виночерпий, слуга, подающий питьё`,kind:`noun`},{lesson:87,arabic:`خَمْرٌ`,russian:`виноград, из которого делают вино; переносное или диалектное значение в объяснении автора`,kind:`noun`},{lesson:87,arabic:`تَحَالَمَ – يَتَحَالَمُ`,russian:`выдумать сновидение, притвориться видевшим сон`,kind:`verb`},{lesson:87,arabic:`حَبَلَةٌ`,russian:`виноградная лоза`,kind:`noun`},{lesson:87,arabic:`اِسْتَعْبَرَ – يَسْتَعْبِرُ`,russian:`попросить истолковать сновидение`,kind:`verb`},{lesson:88,arabic:`عَجَفٌ`,russian:`крайняя худоба, истощение`,kind:`masdar`},{lesson:88,arabic:`ضِغْثٌ ج أَضْغَاثٌ`,russian:`связка смешанных растений; переносно — путаница`,kind:`noun`},{lesson:88,arabic:`أَضْغَاثُ أَحْلَامٍ`,russian:`бессвязные, спутанные сновидения`,kind:`expression`},{lesson:88,arabic:`أُمَّةٌ`,russian:`длительный промежуток времени; не «народ» и не «религия»`,kind:`noun`},{lesson:88,arabic:`اِدَّكَرَ – يَدَّكِرُ`,russian:`вспомнить; вариант اِذْتَكَرَ с ассимиляцией`,kind:`verb`},{lesson:88,arabic:`أَعْضَلَ – يُعْضِلُ`,russian:`стать трудноразрешимым, поставить в затруднение`,kind:`verb`},{lesson:88,arabic:`دَأْبٌ / دَأَبٌ`,russian:`непрерывное усердие, постоянный труд; не только обычай или привычка`,kind:`masdar`},{lesson:88,arabic:`سُوسٌ`,russian:`жучки, портящие зерно, зерновой вредитель`,kind:`noun`},{lesson:88,arabic:`حَصَّنَ – يُحَصِّنُ`,russian:`сохранить в надёжном месте, уберечь; здесь — сберечь зерно`,kind:`verb`},{lesson:88,arabic:`غَاثَ – يَغِيثُ`,russian:`оросить дождём; о дожде и местности`,kind:`verb`},{lesson:88,arabic:`اِسْتَحْصَدَ – يَسْتَحْصِدُ`,russian:`созреть для жатвы; о посеве`,kind:`verb`},{lesson:89,arabic:`أَنَاةٌ`,russian:`неторопливость, осмотрительность`,kind:`noun`},{lesson:89,arabic:`هُرْيٌ ج أَهْرَاءٌ`,russian:`зернохранилище, амбар`,kind:`noun`},{lesson:89,arabic:`عَمَالَةٌ`,russian:`исполнение государственной должности, служба правителю`,kind:`noun`},{lesson:89,arabic:`اِسْتَحْفَظَ – يَسْتَحْفِظُ`,russian:`поручить хранить, доверить на хранение`,kind:`verb`},{lesson:90,arabic:`رَحْلٌ ج رِحَالٌ`,russian:`поклажа, дорожные мешки или вместилища; не только «седло»`,kind:`noun`},{lesson:90,arabic:`مَارَ – يَمِيرُ`,russian:`доставить продовольствие, снабдить пищей; не مَارَ – يَمُورُ «колебаться»`,kind:`verb`},{lesson:90,arabic:`مِيرَةٌ`,russian:`продовольствие, привезённое из другой местности`,kind:`noun`},{lesson:90,arabic:`مَوْثِقٌ`,russian:`крепкое обязательство, подтверждённый клятвой договор`,kind:`noun`},{lesson:90,arabic:`عَيْنٌ لَامَّةٌ`,russian:`сглаз, причиняющий вред`,kind:`expression`},{lesson:91,arabic:`سِقَايَةٌ`,russian:`чаша для питья, используемая как мера; не «снабжение водой»`,kind:`noun`},{lesson:91,arabic:`دِينُ الْمَلِكِ`,russian:`правовой порядок, установления царя; не его религиозное убеждение`,kind:`expression`},{lesson:91,arabic:`اِبْتَأَسَ – يَبْتَئِسُ`,russian:`огорчиться, опечалиться`,kind:`verb`},{lesson:91,arabic:`آكَلَ – يُؤَاكِلُ`,russian:`есть вместе с кем-либо`,kind:`verb`},{lesson:92,arabic:`اِسْتَيْأَسَ – يَسْتَيْئِسُ`,russian:`полностью потерять надежду`,kind:`verb`},{lesson:92,arabic:`نَجِيٌّ`,russian:`ведущий тайный разговор; также — тайная беседа`,kind:`noun`},{lesson:92,arabic:`بَثٌّ`,russian:`невыносимая скорбь, о которой хочется рассказать; не «распространение»`,kind:`noun`},{lesson:92,arabic:`رَوْحُ اللهِ`,russian:`милость Аллаха и даруемое Им облегчение`,kind:`expression`},{lesson:93,arabic:`أَزْجَى – يُزْجِي`,russian:`прогнать, оттолкнуть; здесь — о товаре, который торговцы не желают принять`,kind:`verb`},{lesson:93,arabic:`بِضَاعَةٌ مُزْجَاةٌ`,russian:`малопригодный, малоценный товар, который с трудом принимают`,kind:`expression`},{lesson:93,arabic:`اِرْفَضَّ – يَرْفَضُّ`,russian:`обильно потечь, пролиться; о слезах`,kind:`verb`},{lesson:93,arabic:`عِضَادَةٌ`,russian:`вертикальный боковой брус дверного проёма, косяк`,kind:`noun`},{lesson:93,arabic:`قَتُورٌ`,russian:`скупой, стеснённый в расходах`,kind:`adjective`},{lesson:93,arabic:`فُصُولٌ`,russian:`уход из местности, отправление в путь; не «главы»`,kind:`masdar`},{lesson:93,arabic:`فَنَّدَ – يُفَنِّدُ`,russian:`обвинить в старческом слабоумии, объявить речь неразумной`,kind:`verb`},{lesson:93,arabic:`فَنَدٌ`,russian:`старческое ослабление разума и суждения`,kind:`noun`},{lesson:93,arabic:`مَنْجَعٌ ج مَنَاجِعُ`,russian:`место, куда перекочёвывают ради пастбища`,kind:`noun`},{lesson:93,arabic:`نَزَغَ – يَنْزَغُ بَيْنَ`,russian:`посеять раздор между людьми, подстрекнуть к ссоре`,kind:`verb`},{lesson:93,arabic:`تَشَاحَنَ – يَتَشَاحَنُ`,russian:`враждовать друг с другом`,kind:`verb`},{lesson:93,arabic:`مَرْمَرٌ`,russian:`мрамор`,kind:`noun`},{lesson:93,arabic:`شَرَعًا`,russian:`на равных, в одинаковой доле; не «по шариату»`,kind:`adverb`},{lesson:94,arabic:`وَخَامَةٌ`,russian:`тяжесть и пагубность последствий`,kind:`masdar`}];export{e as part11Glossary};